type KnowledgeDocument = {
  documentId: string;
  title: string;
  siteId: string;
  simulationType: "equipment" | "fire-gas";
  hazardTypes: string[];
  applicableRoles: string[];
  applicableZoneIds: string[];
  substanceIds?: string[];
  language: string;
  version: string;
  status: "draft" | "approved" | "retired";
  effectiveFrom: string;
  expiresAt?: string;
  sourceReference: string;
};

type PersonalizedGuidance = {
  guidanceId: string;
  runId: string;
  workerId: string;

  hazardIds: string[];
  actionCode: string;
  routeVersion?: number;
  profileVersion: number;

  locale: string;
  primaryMessageKey: string;
  supplementalExplanation?: string;

  evidence: {
    documentId: string;
    documentVersion: string;
    chunkId: string;
  }[];

  mode: "template" | "rag-assisted";
  generatedAt: string;
  expiresAt: string;
};
